        const prior=shipment.items.map(x=>Number(x.receivedQty||0));
        if(targets.some((target,index)=>!wholeQty(target)||target<prior[index]||target>Number(shipment.items[index].qty)))return fail('Jumlah kumulatif diterima per SKU tidak valid.');
        if(values.status==='Partial'&&(!targets.some((target,index)=>target>prior[index])||targets.every((target,index)=>target===Number(shipment.items[index].qty))))return fail('Untuk Partial, jumlah harus bertambah dan setidaknya satu SKU masih tersisa.');
